optimization-iteration.patch:
diff --git a/scripts/bot-evaluation/host.ts b/scripts/bot-evaluation/host.ts
index 7f7cdd74..f8b670ec 100644
--- a/scripts/bot-evaluation/host.ts
+++ b/scripts/bot-evaluation/host.ts
@@ -72,7 +72,7 @@ function send(value: unknown) {
   // result and cleanup flushes immediately. No buffered evidence crosses an
   // engine call that could hang; the supervisor retains the confirmed prefix.
   if (
-    outputBuffer.length >= 16 * 1024 ||
+    outputBuffer.length >= 4096 ||
     (value as { type?: string }).type !== "event"
   )
     flushOutput();
